import {
  Field,
  FieldDescription,
  FieldGroup,
  FieldLabel,
  FieldSet,
} from "@/registry/erbium/ui/field";
import { Textarea } from "@/registry/erbium/ui/textarea";

export default function FieldTextarea() {
  return (
    <div className="w-full max-w-md">
      <FieldSet>
        <FieldGroup>
          <Field>
            <FieldLabel>Feedback</FieldLabel>
            <Textarea placeholder="Your feedback helps us improve..." rows={4} />
            <FieldDescription>Share your thoughts about our service.</FieldDescription>
          </Field>
        </FieldGroup>
      </FieldSet>
    </div>
  );
}

import ExampleFieldTextarea from "../examples/field-textarea";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <ExampleFieldTextarea />
  </div>
);

export default Example;
